const body = $json.body ?? $json;
const title = String(body.title ?? '').trim();
const brief = String(body.brief ?? '').trim();
const audience = String(body.audience ?? 'general audience').trim();
const language = String(body.language ?? 'English').trim();
if (!title || !brief) throw new Error('title and brief are required');
if (title.length > 180 || brief.length > 5000) throw new Error('title or brief is too long');
return [{ json: { requestId: `ys-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`, fictional: true, title, brief, audience, language, requestedAt: new Date().toISOString(), provider: 'gemini' } }];

